cat > probe_routes_test.go <<'EOF'
package main

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"
)

func TestProbeRoutes(t *testing.T) {
	mux := routes()
	if mux == nil {
		t.Fatal("routes() returned nil")
	}
	store := NewStore(time.Minute)
	_ = store
	handler := http.Handler(mux)

	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/healthz", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("healthz = %d, want 200", rec.Code)
	}
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("POST", "/session?id=r1&user=u", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("create = %d, want 200", rec.Code)
	}
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/session?id=r1", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("get = %d, want 200", rec.Code)
	}
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/nonexistent", nil))
	if rec.Code != http.StatusNotFound {
		t.Fatalf("unknown route = %d, want 404", rec.Code)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_routes_test.go

